<template><view class="rpg-mresult"><view v-if="snapshot" class="rpg-mresult__card"><view class="rpg-mresult__header"><text>{{ snapshot.mode==='PK'?'PK结算':'合作结算' }}</text><text>{{ summary }}</text></view><view v-if="snapshot.mode==='COOP'" class="rpg-mresult__team">团队进球 {{ snapshot.teamContribution }}/{{ snapshot.teamTarget }} · {{ snapshot.teamCompleted?'挑战成功':'未完全完成' }}</view><view class="rpg-mresult__players"><view v-for="p in snapshot.players" :key="p.playerId" :class="{'rpg-mresult__self':p.playerId===selfId}"><strong>#{{ p.rank }}</strong><text>{{ p.displayName }}</text><text>进度 {{ p.overallCompletionPercent }}%</text><text>射门 {{ p.attempts||0 }}</text><text>进球 {{ p.successes||0 }}</text><text>{{ p.score }}分</text></view></view><button :disabled="snapshot.status!=='FINISHED'" @click="back">返回点球首页</button></view></view></template>
<script lang="ts">import type { RoomSnapshot } from '../../../game-platform/multiplayer/types';import { clearPenaltyMultiplayer,getPenaltyMultiplayerClient,publishPenaltyMultiplayer } from '../../runtime/multiplayer-runtime';import { configureCallerReturnUrl,returnToCaller } from '../../../game-platform/runtime/navigation';export default{name:'RpgMultiResult',data(){return{snapshot:null as RoomSnapshot|null,unsubscribe:null as (()=>void)|null}},computed:{selfId():string{return getPenaltyMultiplayerClient()?.bootstrap.identity.playerId??''},summary():string{if(this.snapshot?.status!=='FINISHED')return'等待其他玩家完成…';if(this.snapshot.mode==='COOP')return this.snapshot.teamCompleted?'团队挑战成功':'团队挑战未完全完成';const p=this.snapshot.players.find(x=>x.playerId===this.selfId);return p?`你的排名：第${p.rank}名`:''}},onLoad(q:Record<string,string|undefined>){configureCallerReturnUrl(q?.returnUrl,'/pages-penalty-game/home/index');const c=getPenaltyMultiplayerClient();if(!c){returnToCaller();return}this.unsubscribe=c.store.subscribe(s=>{this.snapshot=s;if(s?.status==='FINISHED')publishPenaltyMultiplayer(s)})},onUnload(){this.unsubscribe?.()},methods:{back(){if(this.snapshot?.status!=='FINISHED')return;clearPenaltyMultiplayer();returnToCaller({delta:2})}}}</script>
<style scoped>.rpg-mresult{display:flex;align-items:center;justify-content:center;box-sizing:border-box;width:100vw;height:100vh;padding:18px;background:linear-gradient(145deg,#def4ff,#fff2c0);font-family:"Microsoft YaHei",sans-serif;color:#244f6c}.rpg-mresult__card{width:min(920px,94vw);padding:20px;border:3px solid #2b89ca;border-radius:20px;background:#fff}.rpg-mresult__header{display:flex;justify-content:space-between;align-items:center}.rpg-mresult__header text:first-child{color:#0878c9;font-size:29px;font-weight:900}.rpg-mresult__team{margin:10px 0;padding:10px;border-radius:10px;background:#e7f5fc;text-align:center;font-weight:900}.rpg-mresult__players{margin:12px 0}.rpg-mresult__players view{display:grid;grid-template-columns:44px minmax(80px,1fr) 100px 80px 80px 80px;gap:8px;padding:8px;border-bottom:1px solid #d5e7f1}.rpg-mresult__self{background:#fff3c9;color:#176e9f;font-weight:900}.rpg-mresult button{display:flex;align-items:center;justify-content:center;width:220px;height:44px;margin:auto;padding:0;border:0;border-radius:999px;background:#2d98db;color:#fff;font-weight:900}</style>
